function bookByCode(code){return books.find(b=>b.code===code)||books[0]}
function currentBook(){return byName[state.reading.book]||books[0]}
function normalizePoint(p,fallback){const b=byName[p?.book]||fallback||currentBook();const ch=Math.max(1,Math.min(Number(p?.chapter)||1,b.chapters));const verse=Math.max(1,Number(p?.verse)||1);return {book:b.name,chapter:ch,verse}}
function normalizeRange(r,fallback){const from=normalizePoint(r?.from||r,fallback);const to=r?.to?normalizePoint(r.to,byName[r.to.book]||fallback):null;return {from,to:to&&((to.book!==from.book)||(to.chapter!==from.chapter)||(to.verse!==from.verse))?to:null}}
function parseLegacyReference(ref,book){
  const raw=String(ref||'').trim(); if(!raw)return null;
  const clean=raw.replace(/[–—]/g,'-').replace(/\s+/g,' ');
  const pieces=clean.split(/\s*-\s*/);
  const parsePoint=(text,base)=>{
    const s=String(text||'').trim();
    let m=s.match(/^(?:(.+?)\s+)?(\d+)\s*:\s*(\d+)$/);
    if(m){const b=byName[m[1]?.trim()]||base||book;return {book:b.name,chapter:Number(m[2]),verse:Number(m[3])};}
    m=s.match(/^(?:(.+?)\s+)?(\d+)$/);
    if(m){const b=byName[m[1]?.trim()]||base||book;return {book:b.name,chapter:Number(m[2]),verse:base?.verse||1};}
    return null;
  };
  const from=parsePoint(pieces[0],book);
  if(!from)return null;
  if(pieces.length===1)return normalizeRange({from,to:null},book);
  const endpoint=pieces.slice(1).join('-').trim();
  let to=parsePoint(endpoint,byName[from.book]||book);
  if(/^\d+$/.test(endpoint))to={book:from.book,chapter:from.chapter,verse:Number(endpoint)};
  if(/^\d+\s*:\s*\d+$/.test(endpoint))to={book:from.book,chapter:Number(endpoint.split(':')[0]),verse:Number(endpoint.split(':')[1])};
  return normalizeRange({from,to},book);
}
function formatRange(r){if(!r?.from)return '—';const a=r.from,b=r.to;if(!b)return `${a.chapter}:${a.verse}`;if(a.book===b.book&&a.chapter===b.chapter)return `${a.chapter}:${a.verse}–${b.verse}`;if(a.book===b.book)return `${a.chapter}:${a.verse}–${b.chapter}:${b.verse}`;return `${a.book} ${a.chapter}:${a.verse}–${b.book} ${b.chapter}:${b.verse}`}
