async function syncStateToCloud(){
  if(!cloudUser||cloudLoading)return;
  const rows=state.questions.map((q,i)=>questionRow(q,i));
  if(rows.length){
    const {error}=await supabaseClient.from('questions').upsert(rows,{onConflict:'id'});if(error)throw error;
    const researchRows=state.questions.map(q=>({question_id:isUuid(q.uid)?q.uid:null,user_id:cloudUser.id,status:q.status,research_notes:q.investigation||'',sources:q.sources||'',conclusion:q.conclusion||'',search_query:buildResearchQuery(q),floating_x:q.researchUi?.x??null,floating_y:q.researchUi?.y??null,updated_at:new Date().toISOString()})).filter(r=>r.question_id);
    if(researchRows.length){const {error:e2}=await supabaseClient.from('research').upsert(researchRows,{onConflict:'question_id'});if(e2)throw e2}
  }
  const {error:e3}=await supabaseClient.from('reading_progress').upsert(readingRows(),{onConflict:'user_id,book_code'});if(e3)throw e3;
}
function applyCloudQuestions(rows,researchRows){
  const researchMap=new Map((researchRows||[]).map(r=>[r.question_id,r]));
  state.questions=(rows||[]).sort((a,b)=>a.sort_order-b.sort_order).map(r=>{const rr=researchMap.get(r.id);const b=byName[r.book]||bookByCode(r.book_code);const parsed=parseLegacyReference(r.verse,b)||{from:{book:b.name,chapter:Number(r.chapter)||1,verse:1},to:null};const additional=String(r.additional_reference||'').split(';').map(x=>parseLegacyReference(x,b)).filter(Boolean);return {uid:r.id,id:r.question_id,code:b.code,book:b.name,chapter:parsed.from.chapter,primaryReference:parsed,additionalReferences:additional,references:[formatRange(parsed),...additional.map(formatRange)],question:r.question||'',why:r.why_asked||'',category:CATEGORIES.includes(r.category)?r.category:'Other',status:STATUSES.includes(r.status)?r.status:'Unanswered',related:Array.isArray(r.related_questions)?r.related_questions:[],investigation:rr?.research_notes||r.investigation_answer||'',sources:rr?.sources||r.sources||'',conclusion:rr?.conclusion||r.conclusion||'',createdAt:r.created_at||new Date().toISOString(),researchUi:{x:rr?.floating_x??null,y:rr?.floating_y??null,minimized:false}}});
}
async function loadCloudState(){
  cloudLoading=true;
  const [{data:questions,error:qErr},{data:research,error:rErr},{data:progress,error:pErr}]=await Promise.all([
    supabaseClient.from('questions').select('*').eq('user_id',cloudUser.id).order('sort_order',{ascending:true}),
    supabaseClient.from('research').select('*').eq('user_id',cloudUser.id),
    supabaseClient.from('reading_progress').select('*').eq('user_id',cloudUser.id)
  ]);
  if(qErr||rErr||pErr)throw qErr||rErr||pErr;
  const hasCloud=Boolean((questions||[]).length||(progress||[]).length);
  if(hasCloud){
    applyCloudQuestions(questions||[],research||[]);
    state.reading.completed={};state.reading.positions={};
    (progress||[]).forEach(r=>{const b=byName[r.book]||bookByCode(r.book_code);state.reading.positions[b.name]={chapter:Number(r.current_chapter)||1,verse:Number(r.current_verse)||1};(r.completed_chapters||[]).forEach(c=>state.reading.completed[b.name+'|'+c]=true)});
    const lastRow=(progress||[]).find(r=>r.is_last)||((progress||[]).slice().sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)))[0]);const last=lastRow?{book:(byName[lastRow.book]||bookByCode(lastRow.book_code)).name,chapter:Number(lastRow.current_chapter)||1,verse:Number(lastRow.current_verse)||1}:{book:'Pydāish',chapter:1,verse:1};state.reading.last=last;state.reading.book=last.book;state.reading.chapter=last.chapter;state.reading.verse=last.verse;
  }else{
    if(state.questions.length)await syncStateToCloud();
    else await syncStateToCloud();
  }
  cloudLoading=false;cloudReady=true;save();
}
