async function bootAuth(){
  document.getElementById('googleSignIn').onclick=async()=>{setAuthMessage('Opening Google…');const {error}=await supabaseClient.auth.signInWithOAuth({provider:'google',options:{redirectTo:window.location.href}});if(error)setAuthMessage(error.message)};
  document.getElementById('signOutButton').onclick=async()=>{await supabaseClient.auth.signOut();window.location.reload()};
  supabaseClient.auth.onAuthStateChange((event,session)=>{if(session)setTimeout(()=>startAuthenticatedApp(session),0);else{cloudUser=null;cloudReady=false;setAuthVisible(true);}});
  const {data,error}=await supabaseClient.auth.getSession();
  if(error){setAuthMessage(error.message);setAuthVisible(true);return}
  if(data.session)await startAuthenticatedApp(data.session);else setAuthVisible(true);
}
function migrate(){
  state.reading=state.reading||{book:'Pydāish',chapter:1,verse:1,completed:{}};
  state.reading.completed=state.reading.completed||{};
  state.reading.positions=state.reading.positions||{};
  if(!state.reading.positions[state.reading.book])state.reading.positions[state.reading.book]={chapter:Number(state.reading.chapter)||1,verse:Number(state.reading.verse)||1};
  state.reading.last=state.reading.last||{book:state.reading.book,chapter:Number(state.reading.chapter)||1,verse:Number(state.reading.verse)||1};
  state.questions=Array.isArray(state.questions)?state.questions:[];
  state.questions.forEach(q=>{
    q.uid=q.uid||uid(); q.code=q.code||bookByCode(q.code).code; q.book=byName[q.book]?.name||bookByCode(q.code).name;
    q.category=CATEGORIES.includes(q.category)?q.category:'Other'; q.status=STATUSES.includes(q.status)?q.status:'Unanswered';
    if(!q.primaryReference){
      const first=(q.references||[])[0]; q.primaryReference=parseLegacyReference(first,q.book?byName[q.book]:currentBook())||{from:{book:q.book||'Pydāish',chapter:Number(q.chapter)||1,verse:1},to:null};
    }else q.primaryReference=normalizeRange(q.primaryReference,byName[q.book]||currentBook());
    q.additionalReferences=Array.isArray(q.additionalReferences)?q.additionalReferences.map(x=>normalizeRange(x,byName[q.book]||currentBook())).filter(Boolean):[];
    if(!q.additionalReferences.length && Array.isArray(q.references)&&q.references.length>1)q.additionalReferences=q.references.slice(1).map(x=>parseLegacyReference(x,byName[q.book]||currentBook())).filter(Boolean);
    q.references=[formatRange(q.primaryReference),...(q.additionalReferences||[]).map(formatRange)];
    q.related=Array.isArray(q.related)?q.related:[]; q.investigation=q.investigation||'';q.sources=q.sources||'';q.conclusion=q.conclusion||'';
    q.researchUi=q.researchUi||{x:null,y:null,minimized:false};
  });
  if(!state.research)state.research={};
  if(!state.selectedLanguage)state.selectedLanguage='ur';
  if(!state.translations)state.translations=[]; if(!state.cache)state.cache={};
  save();
}
